def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            result += chr((ord(char) - base + shift) % 26 + base)
        else:
            result += char
    return result

def caesar_cipher(text: str, shift: int) -> str:
    base_low = ord('a')
    base_up = ord('A')
    result = []

    for char in text:
        if 'a' <= char <= 'z':
            result.append(chr(base_low + (ord(char) - base_low + shift) % 26))
        elif 'A' <= char <= 'Z':
            result.append(chr(base_up + (ord(char) - base_up + shift) % 26))
        else:
            result.append(char)

    return ''.join(result)

def fibonacci(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def flatten(lst: list) -> list:
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def is_palindrome(s: str) -> bool:
    cleaned = ''.join(c.lower() for c in s if c.isalnum())
    return cleaned == cleaned[::-1]

