def word_frequency(text: str) -> dict[str, int]:
    import string
    from collections import Counter

    words = text.split()
    result = Counter()

    for word in words:
        clean_word = word.lower().strip(string.punctuation)
        if clean_word:
            result[clean_word] += 1

    return dict(result)
